// backend/tests/integration/bank-p2p-transfer.test.ts
// Testes de integração para transferência P2P

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { v4 as uuidv4 } from 'uuid';
import { pool } from '../../src/core/database/pool';
import { bankP2PTransferService } from '../../src/core/unifybank/bank-p2p-transfer.service';
import { accountService } from '../../src/core/economy/accounts/account.service';
import { resolveGlobalUserId } from '../../src/core/identity/identity.utils';

describe('Bank P2P Transfer - Integração', () => {
  const testTenantId = uuidv4();
  let fromUserId: string;
  let toUserId: string;
  let fromAccountId: string;
  let toAccountId: string;

  beforeAll(async () => {
    // Criar tenant de teste
    await pool.query(
      `INSERT INTO tenants (tenant_id, name, city_id)
       VALUES ($1, 'Test Tenant', NULL)
       ON CONFLICT (tenant_id) DO NOTHING`,
      [testTenantId]
    );

    // Criar usuários de teste
    fromUserId = uuidv4();
    toUserId = uuidv4();

    // Criar global_users
    const fromGlobalUserId = uuidv4();
    const toGlobalUserId = uuidv4();

    await pool.query(
      `INSERT INTO global_users (global_user_id, full_name, created_at)
       VALUES ($1, 'From User', now()),
              ($2, 'To User', now())
       ON CONFLICT (global_user_id) DO NOTHING`,
      [fromGlobalUserId, toGlobalUserId]
    );

    // Criar users locais
    await pool.query(
      `INSERT INTO users (user_id, tenant_id, email, global_user_id, created_at)
       VALUES ($1, $2, 'from@test.com', $3, now()),
              ($4, $2, 'to@test.com', $5, now())
       ON CONFLICT (user_id) DO NOTHING`,
      [fromUserId, testTenantId, fromGlobalUserId, toUserId, toGlobalUserId]
    );

    // Criar ou buscar contas
    const fromAccount = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      fromUserId,
      'BRL'
    );
    const toAccount = await accountService.getOrCreateUserPrimaryAccount(
      testTenantId,
      toUserId,
      'BRL'
    );

    fromAccountId = fromAccount.accountId;
    toAccountId = toAccount.accountId;

    // Depositar saldo inicial no remetente
    await pool.query(
      `UPDATE accounts SET balance = 1000.00 WHERE account_id = $1`,
      [fromAccountId]
    );
  });

  afterAll(async () => {
    // Limpar dados de teste (opcional, pois testes devem usar rollback)
    // Em produção, usar transações com rollback
    try {
      await pool.query(`DELETE FROM transactions WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM ledger WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM accounts WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM users WHERE tenant_id = $1`, [testTenantId]);
      await pool.query(`DELETE FROM tenants WHERE tenant_id = $1`, [testTenantId]);
    } catch (error) {
      // Ignorar erros de limpeza
    }
  });

  describe('Transferência válida', () => {
    it('deve transferir saldo entre usuários com sucesso', async () => {
      const amount = 100;
      const eventId = uuidv4();

      const result = await bankP2PTransferService.transferP2P(testTenantId, {
        fromUserId,
        toUserId,
        amount,
        eventId,
      });

      expect(result).toBeDefined();
      expect(result.transaction).toBeDefined();
      expect(result.transaction.amount).toBe(amount);
      expect(result.transaction.eventId).toBe(eventId);
      expect(result.fromUserId).toBe(fromUserId);
      expect(result.toUserId).toBe(toUserId);
      expect(result.fromAccountBalance).toBe(900); // 1000 - 100
      expect(result.toAccountBalance).toBe(100); // 0 + 100

      // Verificar saldos no banco
      const fromAccount = await accountService.getAccountById(testTenantId, fromAccountId);
      const toAccount = await accountService.getAccountById(testTenantId, toAccountId);

      expect(fromAccount?.balance).toBe(900);
      expect(toAccount?.balance).toBe(100);
    });

    it('deve criar entradas no ledger (double-entry)', async () => {
      const amount = 50;
      const eventId = uuidv4();

      await bankP2PTransferService.transferP2P(testTenantId, {
        fromUserId,
        toUserId,
        amount,
        eventId,
      });

      // Verificar ledger
      const ledgerEntries = await pool.query(
        `SELECT entry_type, amount, balance_before, balance_after
         FROM ledger
         WHERE tenant_id = $1 AND transaction_id IN (
           SELECT transaction_id FROM transactions WHERE event_id = $2
         )
         ORDER BY entry_type`,
        [testTenantId, eventId]
      );

      expect(ledgerEntries.rows.length).toBe(2);

      const debit = ledgerEntries.rows.find((e) => e.entry_type === 'debit');
      const credit = ledgerEntries.rows.find((e) => e.entry_type === 'credit');

      expect(debit).toBeDefined();
      expect(credit).toBeDefined();
      expect(parseFloat(debit.amount)).toBe(amount);
      expect(parseFloat(credit.amount)).toBe(amount);

      // Verificar que ledger está balanceado
      const sumResult = await pool.query(
        `SELECT 
           SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE -amount END) as balance
         FROM ledger
         WHERE tenant_id = $1 AND transaction_id IN (
           SELECT transaction_id FROM transactions WHERE event_id = $2
         )`,
        [testTenantId, eventId]
      );

      const balance = parseFloat(sumResult.rows[0].balance || '0');
      expect(balance).toBe(0); // Deve estar balanceado
    });
  });

  describe('Validações de negócio', () => {
    it('deve rejeitar transferência com saldo insuficiente', async () => {
      const amount = 10000; // Mais que o saldo disponível
      const eventId = uuidv4();

      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount,
          eventId,
        })
      ).rejects.toThrow('Insufficient balance');
    });

    it('deve rejeitar transferência para si mesmo', async () => {
      const amount = 100;
      const eventId = uuidv4();

      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId: fromUserId, // Mesmo usuário
          amount,
          eventId,
        })
      ).rejects.toThrow('Cannot transfer to yourself');
    });

    it('deve rejeitar amount <= 0', async () => {
      const eventId = uuidv4();

      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount: 0,
          eventId,
        })
      ).rejects.toThrow('Amount must be greater than zero');

      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount: -10,
          eventId,
        })
      ).rejects.toThrow('Amount must be greater than zero');
    });

    it('deve rejeitar transferência para usuário inexistente', async () => {
      const amount = 100;
      const eventId = uuidv4();
      const nonExistentUserId = uuidv4();

      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId: nonExistentUserId,
          amount,
          eventId,
        })
      ).rejects.toThrow('Destination user not found');
    });
  });

  describe('Idempotência', () => {
    it('deve retornar a mesma transação ao repetir eventId', async () => {
      const amount = 50;
      const eventId = uuidv4();

      // Primeira transferência
      const result1 = await bankP2PTransferService.transferP2P(testTenantId, {
        fromUserId,
        toUserId,
        amount,
        eventId,
      });

      // Segunda transferência com mesmo eventId
      const result2 = await bankP2PTransferService.transferP2P(testTenantId, {
        fromUserId,
        toUserId,
        amount,
        eventId,
      });

      // Deve retornar a mesma transação
      expect(result1.transaction.transactionId).toBe(result2.transaction.transactionId);
      expect(result1.transaction.eventId).toBe(result2.transaction.eventId);

      // Saldos não devem mudar na segunda chamada
      const fromAccount = await accountService.getAccountById(testTenantId, fromAccountId);
      const toAccount = await accountService.getAccountById(testTenantId, toAccountId);

      // Saldo deve ser o mesmo da primeira transferência (não duplicado)
      // Se não fosse idempotente, seria amount * 2
      expect(fromAccount?.balance).toBeLessThan(1000);
      expect(toAccount?.balance).toBeGreaterThan(0);
    });

    it('não deve criar múltiplas transações com mesmo eventId', async () => {
      const amount = 25;
      const eventId = uuidv4();

      // Executar múltiplas vezes
      await Promise.all([
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount,
          eventId,
        }),
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount,
          eventId,
        }),
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount,
          eventId,
        }),
      ]);

      // Verificar que apenas uma transação foi criada
      const transactions = await pool.query(
        `SELECT COUNT(*) as count
         FROM transactions
         WHERE tenant_id = $1 AND event_id = $2`,
        [testTenantId, eventId]
      );

      expect(parseInt(transactions.rows[0].count)).toBe(1);
    });
  });

  describe('Transação atômica', () => {
    it('deve garantir que saldo nunca fica negativo', async () => {
      // Resetar saldo para teste
      await pool.query(
        `UPDATE accounts SET balance = 100.00 WHERE account_id = $1`,
        [fromAccountId]
      );

      const amount = 150; // Mais que o saldo disponível
      const eventId = uuidv4();

      // Deve falhar antes de atualizar qualquer saldo
      await expect(
        bankP2PTransferService.transferP2P(testTenantId, {
          fromUserId,
          toUserId,
          amount,
          eventId,
        })
      ).rejects.toThrow();

      // Verificar que saldo não mudou (rollback funcionou)
      const fromAccount = await accountService.getAccountById(testTenantId, fromAccountId);
      expect(fromAccount?.balance).toBe(100); // Não mudou
    });

    it('deve garantir ledger balanceado mesmo em caso de erro', async () => {
      // Verificar que todas as transações têm ledger balanceado
      const ledgerCheck = await pool.query(
        `SELECT transaction_id,
           SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE -amount END) as balance
         FROM ledger
         WHERE tenant_id = $1
         GROUP BY transaction_id
         HAVING SUM(CASE WHEN entry_type = 'debit' THEN amount ELSE -amount END) != 0`,
        [testTenantId]
      );

      // Não deve haver transações desbalanceadas
      expect(ledgerCheck.rows.length).toBe(0);
    });
  });
});




























